const Theme = (function() { 'use strict'; const THEME_KEY = 'go-tutorial-theme'; const themes = { light: 'light', dark: 'dark' }; let currentTheme = themes.light; function init() { const savedTheme = localStorage.getItem(THEME_KEY); if (savedTheme && themes[savedTheme]) { currentTheme = savedTheme; } else { currentTheme = detectSystemTheme(); } applyTheme(currentTheme); createThemeToggle(); console.log('[Theme] 初始化完成，当前主题:', currentTheme); } function detectSystemTheme() { if (window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches) { return themes.dark; } return themes.light; } function applyTheme(theme) { document.documentElement.setAttribute('data-theme', theme); if (theme === themes.dark) { document.body.classList.add('dark-theme'); document.body.classList.remove('light-theme'); } else { document.body.classList.add('light-theme'); document.body.classList.remove('dark-theme'); } currentTheme = theme; } function toggle() { const newTheme = currentTheme === themes.light ? themes.dark : themes.light; setTheme(newTheme); } function setTheme(theme) { if (!themes[theme]) { console.error('[Theme] 无效的主题:', theme); return; } applyTheme(theme); localStorage.setItem(THEME_KEY, theme); window.dispatchEvent(new CustomEvent('themechange', { detail: { theme } })); } function getCurrentTheme() { return currentTheme; } function createThemeToggle() { if (document.querySelector('.theme-toggle')) { return; } const toggle = document.createElement('button'); toggle.className = 'theme-toggle'; toggle.innerHTML = getThemeIcon(); toggle.title = '切换主题'; toggle.addEventListener('click', function(e) { e.preventDefault(); toggle(); }); const sidebar = document.querySelector('.sidebar'); if (sidebar) { const header = sidebar.querySelector('h3'); if (header) { toggle.style.cssText = ` position: absolute; right: 20px; top: 20px; background: none; border: none; cursor: pointer; font-size: 1.5em; padding: 5px; border-radius: 5px; transition: all 0.3s ease; `; toggle.onmouseover = () => toggle.style.background = '#e3f2fd'; toggle.onmouseout = () => toggle.style.background = 'none'; header.style.position = 'relative'; header.appendChild(toggle); } } } function getThemeIcon() { return currentTheme === themes.light ? '🌙' : '☀️'; } function updateThemeIcon() { const toggle = document.querySelector('.theme-toggle'); if (toggle) { toggle.innerHTML = getThemeIcon(); } } if (window.matchMedia) { window.matchMedia('(prefers-color-scheme: dark)').addEventListener('change', function(e) { if (!localStorage.getItem(THEME_KEY)) { setTheme(e.matches ? themes.dark : themes.light); } }); } return { init, toggle, setTheme, getCurrentTheme, updateThemeIcon }; })(); document.addEventListener('DOMContentLoaded', function() { Theme.init(); }); if (typeof window !== 'undefined') { window.Theme = Theme; }